def transform(grid):
    """Color cells between same-color markers that share a row or column."""
    h, w = len(grid), len(grid[0])
    background = grid[0][0]
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] != background]
    out = [row[:] for row in grid]
    for i, (r, c) in enumerate(points):
        for rr, cc in points[i + 1:]:
            if r == rr:
                for x in range(min(c, cc) + 1, max(c, cc)):
                    out[r][x] = 3
            elif c == cc:
                for x in range(min(r, rr) + 1, max(r, rr)):
                    out[x][c] = 3
    return out
